param([Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop'
$compiler=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
$source=Join-Path $PSScriptRoot 'Controller\UmaDesktopController.cs'
$out=Join-Path $OutputDirectory 'UmaDesktopController.exe'
& $compiler /nologo /target:winexe /platform:x64 /optimize+ /codepage:65001 ("/out:"+$out) /r:System.Windows.Forms.dll /r:System.Drawing.dll /r:System.Web.Extensions.dll /r:System.Core.dll $source (Join-Path $PSScriptRoot 'Assets\Scripts\DesktopPrototype\DesktopProduct.cs') (Join-Path $PSScriptRoot 'Controller\UmaWalkingUpdates.cs') (Join-Path $PSScriptRoot 'Controller\UmaWalkingReleaseTests.cs') (Join-Path $PSScriptRoot 'Assets\Scripts\DesktopPrototype\DesktopProfile.cs') (Join-Path $PSScriptRoot 'Assets\Scripts\DesktopPrototype\DesktopCharacterNames.cs') (Join-Path $PSScriptRoot 'Controller\UmaDesktopNamesTests.cs') (Join-Path $PSScriptRoot 'Controller\UmaDesktopOptions.cs') (Join-Path $PSScriptRoot 'Controller\UmaWalkingPopulation.cs') (Join-Path $PSScriptRoot 'Assets\Scripts\DesktopPrototype\DesktopRules.cs') (Join-Path $PSScriptRoot 'Controller\UmaDesktopLanguage.cs') (Join-Path $PSScriptRoot 'Controller\UmaDesktopData.cs') (Join-Path $PSScriptRoot 'Controller\UmaDesktopOptionsTests.cs') (Join-Path $PSScriptRoot 'Assets\Scripts\DesktopPrototype\DesktopAssetPlan.cs') (Join-Path $PSScriptRoot 'Controller\UmaDesktopRestart.cs') (Join-Path $PSScriptRoot 'Controller\UmaDesktopGroundEditor.cs') (Join-Path $PSScriptRoot 'Controller\UmaDesktopManualEntries.cs') (Join-Path $PSScriptRoot 'Assets\Scripts\DesktopPrototype\DesktopGroundMath.cs') (Join-Path $PSScriptRoot 'Assets\Scripts\DesktopPrototype\DesktopGroundDrag.cs') (Join-Path $PSScriptRoot 'Assets\Scripts\DesktopPrototype\DesktopFootprintMath.cs')
if($LASTEXITCODE -ne 0){throw 'Controller build failed.'}
Write-Output ('Controller built: '+$out)
